CREATE OR REPLACE FUNCTION public.reports_people_rows(_from date,_to date,_filters jsonb,_as_of timestamptz DEFAULT now()) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
WITH bounds AS (SELECT _from::timestamp AT TIME ZONE 'Africa/Johannesburg' start_at,LEAST((_to+1)::timestamp AT TIME ZONE 'Africa/Johannesburg',_as_of,now()) end_at,LEAST(_to,(LEAST(_as_of,now()) AT TIME ZONE 'Africa/Johannesburg')::date) cutoff), admin_ids AS (SELECT user_id FROM public.user_roles WHERE role='admin'), invitations AS (
SELECT i.id::text invitation_id,lower(btrim(i.email)) email,i.contact_person name,'agency_staff'::text typ,i.agency_id,i.accepted_at,i.first_sent_at,i.source,i.created_at FROM public.agency_invitations i
UNION ALL SELECT i.id::text,lower(btrim(i.email)),i.talent_name,'talent',NULL::uuid,i.accepted_at,i.first_sent_at,i.source,i.created_at FROM public.independent_talent_invitations i
UNION ALL SELECT i.id::text,lower(btrim(i.email)),i.talent_name,'talent',i.agency_id,i.accepted_at,i.first_sent_at,'agency',i.created_at FROM public.talent_invitations i WHERE NOT EXISTS(SELECT 1 FROM public.talent_invite_private p WHERE p.invitation_id=i.id AND p.kind IN ('inert','link_request'))), staff AS (
SELECT m.user_id::text person_id,COALESCE(NULLIF(btrim(p.display_name),''),NULLIF(btrim(concat_ws(' ',p.first_name,p.last_name)),''),'Name not recorded') name,lower(btrim(p.email)) email,'agency_staff'::text account_type,array_agg(DISTINCT a.id) agency_ids,array_agg(DISTINCT a.name ORDER BY a.name) agency_names,CASE WHEN bool_or(a.paused_at IS NOT NULL) THEN 'paused' WHEN bool_or(a.status='suspended' OR m.suspended) THEN 'suspended' ELSE 'active' END status,true registered,
(SELECT min(i.accepted_at) FROM invitations i WHERE i.email=lower(btrim(p.email)) AND i.typ='agency_staff' AND i.accepted_at<b.end_at) registered_at,NULL::timestamptz onboarded_at,(SELECT i.source FROM invitations i WHERE i.email=lower(btrim(p.email)) AND i.typ='agency_staff' AND i.accepted_at IS NOT NULL ORDER BY i.accepted_at,i.invitation_id LIMIT 1) source,min(p.created_at) existed_at
FROM public.agency_members m JOIN public.agencies a ON a.id=m.agency_id JOIN public.profiles p ON p.id=m.user_id CROSS JOIN bounds b WHERE p.created_at<b.end_at AND m.created_at<b.end_at AND NOT EXISTS(SELECT 1 FROM admin_ids x WHERE x.user_id=m.user_id) AND NOT EXISTS(SELECT 1 FROM public.talent_profiles d WHERE d.user_id=m.user_id AND d.deleted_at IS NOT NULL) AND (_filters->>'accounts'='all' OR a.is_test=(_filters->>'accounts'='test')) GROUP BY m.user_id,p.display_name,p.first_name,p.last_name,p.email,b.end_at), talent AS (
SELECT t.user_id::text person_id,COALESCE(NULLIF(btrim(t.full_name),''),'Name not recorded') name,lower(btrim(t.email)) email,'talent'::text account_type,COALESCE(l.ids,ARRAY[]::uuid[]) agency_ids,COALESCE(l.names,ARRAY[]::text[]) agency_names,CASE WHEN t.paused_at IS NOT NULL THEN 'paused' WHEN t.suspended_at IS NOT NULL THEN 'suspended' ELSE 'active' END status,true registered,
(SELECT min(i.accepted_at) FROM invitations i WHERE i.email=lower(btrim(t.email)) AND i.typ='talent' AND i.accepted_at<b.end_at) registered_at,CASE WHEN ms.first_validated_upload_at<b.end_at THEN ms.first_validated_upload_at END onboarded_at,(SELECT i.source FROM invitations i WHERE i.email=lower(btrim(t.email)) AND i.typ='talent' AND i.accepted_at IS NOT NULL ORDER BY i.accepted_at,i.invitation_id LIMIT 1) source,t.created_at existed_at
FROM public.talent_profiles t JOIN public.profiles p ON p.id=t.user_id CROSS JOIN bounds b LEFT JOIN public.reports_talent_milestones ms ON ms.user_id=t.user_id LEFT JOIN LATERAL (SELECT array_agg(DISTINCT a.id) ids,array_agg(DISTINCT a.name ORDER BY a.name) names FROM public.agency_talent_links l JOIN public.agencies a ON a.id=l.agency_id WHERE l.talent_user_id=t.user_id AND l.status='active' AND l.ended_at IS NULL AND l.created_at<b.end_at) l ON true WHERE t.deleted_at IS NULL AND t.created_at<b.end_at AND (_filters->>'accounts'='all' OR t.is_test=(_filters->>'accounts'='test')) AND NOT EXISTS(SELECT 1 FROM admin_ids x WHERE x.user_id=t.user_id) AND NOT EXISTS(SELECT 1 FROM public.agency_members m WHERE m.user_id=t.user_id)), scoped_shares AS (
SELECT s.*,lower(btrim(s.loved_one_email)) recipient FROM public.loved_one_shares s JOIN talent t ON t.person_id=(SELECT tp.user_id::text FROM public.talent_profiles tp WHERE tp.id=s.talent_id) CROSS JOIN bounds b WHERE s.access_code_hash IS NOT NULL AND btrim(s.loved_one_email)<>'' AND s.created_at<b.end_at AND (_filters->>'talent'='all' OR (_filters->>'talent'='agency_linked')=(cardinality(t.agency_ids)>0)) AND (_filters->>'source'='all' OR t.source=_filters->>'source') AND (_filters->>'status'='any' OR t.status=_filters->>'status') AND (jsonb_array_length(COALESCE(_filters->'agencies','[]'::jsonb))=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(_filters->'agencies') a WHERE a.value::uuid=ANY(t.agency_ids)))), contacts AS (
SELECT 'recipient:'||md5(s.recipient) person_id,COALESCE(min(NULLIF(btrim(s.loved_one_name),'')),'Name not recorded') name,s.recipient email,'trusted_contact'::text account_type,ARRAY[]::uuid[] agency_ids,ARRAY[]::text[] agency_names,'active'::text status,false registered,min(s.created_at) registered_at,NULL::timestamptz onboarded_at,NULL::text source,min(s.created_at) existed_at FROM scoped_shares s GROUP BY s.recipient), prospects AS (
SELECT 'prospect:'||md5(i.email) person_id,COALESCE(min(NULLIF(btrim(i.name),'')),'Name not recorded') name,i.email,min(i.typ) account_type,COALESCE(array_agg(DISTINCT a.id) FILTER(WHERE a.id IS NOT NULL),ARRAY[]::uuid[]) agency_ids,COALESCE(array_agg(DISTINCT a.name ORDER BY a.name) FILTER(WHERE a.name IS NOT NULL),ARRAY[]::text[]) agency_names,'invited'::text status,false registered,NULL::timestamptz registered_at,NULL::timestamptz onboarded_at,min(i.source) source,min(i.created_at) existed_at FROM invitations i LEFT JOIN public.agencies a ON a.id=i.agency_id CROSS JOIN bounds b WHERE i.first_sent_at IS NOT NULL AND i.first_sent_at<b.end_at AND i.accepted_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE lower(btrim(p.email))=i.email) AND (_filters->>'accounts'='all' OR public.invitation_counts_as_test(i.email,i.agency_id)=(_filters->>'accounts'='test')) GROUP BY i.email), roster AS (SELECT * FROM staff UNION ALL SELECT * FROM talent UNION ALL SELECT * FROM contacts UNION ALL SELECT * FROM prospects), events AS (
SELECT e.actor_id::text person_id,e.created_at occurred_at FROM public.talent_audit_log e CROSS JOIN bounds b WHERE e.action='login' AND e.created_at<b.end_at UNION ALL SELECT 'recipient:'||md5(s.recipient),e.created_at FROM public.loved_one_share_access_events e JOIN scoped_shares s ON s.id=e.share_id CROSS JOIN bounds b WHERE e.event='successful_code' AND e.created_at<b.end_at), document_counts AS (
SELECT u::text person_id,count(*) documents FROM (SELECT d.user_id u FROM public.talent_private_documents d CROSS JOIN bounds b WHERE d.validated_at IS NOT NULL AND d.quarantine_reason IS NULL AND d.created_at>=b.start_at AND d.created_at<b.end_at UNION ALL SELECT d.uploaded_by FROM public.talent_shared_documents d JOIN public.agency_talent_links l ON l.id=d.talent_link_id CROSS JOIN bounds b WHERE d.uploaded_by=l.talent_user_id AND d.validated_at IS NOT NULL AND d.quarantine_reason IS NULL AND d.copied_from_vault_at IS NULL AND d.created_at>=b.start_at AND d.created_at<b.end_at) d GROUP BY u), aggregate AS (
SELECT r.*,count(e.occurred_at) FILTER(WHERE e.occurred_at>=b.start_at) sign_ins,count(DISTINCT (e.occurred_at AT TIME ZONE 'Africa/Johannesburg')::date) FILTER(WHERE e.occurred_at>=b.start_at) active_days,min(e.occurred_at) first_sign_in,max(e.occurred_at) last_sign_in,count(DISTINCT (e.occurred_at AT TIME ZONE 'Africa/Johannesburg')::date) lifetime_days,b.cutoff,b.start_at FROM roster r CROSS JOIN bounds b LEFT JOIN events e USING(person_id) GROUP BY r.person_id,r.name,r.email,r.account_type,r.agency_ids,r.agency_names,r.status,r.registered,r.registered_at,r.onboarded_at,r.source,r.existed_at,b.cutoff,b.start_at), enriched AS (
SELECT a.person_id,a.name,a.email,a.account_type,a.agency_ids,a.agency_names,a.status,a.registered,a.registered_at,a.onboarded_at,a.source,CASE WHEN a.account_type='trusted_contact' THEN 'recipient' WHEN NOT a.registered THEN 'invited' WHEN a.lifetime_days>=2 THEN 'returned' WHEN a.onboarded_at IS NOT NULL THEN 'onboarded' ELSE 'registered' END stage,a.sign_ins,a.active_days,round(a.sign_ins*7.0/GREATEST(1,_to-_from+1),2) average_per_week,a.first_sign_in,a.last_sign_in,CASE WHEN a.last_sign_in IS NOT NULL THEN a.cutoff-(a.last_sign_in AT TIME ZONE 'Africa/Johannesburg')::date END days_since_last,CASE WHEN a.registered_at IS NULL OR (a.cutoff::timestamp AT TIME ZONE 'Africa/Johannesburg')-public.sign_in_capture_started_at()<interval '30 days' THEN NULL ELSE a.cutoff-(COALESCE(a.last_sign_in,a.registered_at) AT TIME ZONE 'Africa/Johannesburg')::date>=30 END dormant,COALESCE(d.documents,0) documents,a.start_at>=public.sign_in_capture_started_at() capture_complete,NULL::text launch_discount_status,NULL::timestamptz keep_by FROM aggregate a LEFT JOIN document_counts d USING(person_id)), filtered AS (
SELECT e.* FROM enriched e WHERE (_filters->>'account_type'='all' OR e.account_type=_filters->>'account_type') AND (e.account_type='trusted_contact' OR ((_filters->>'talent'='all' OR e.account_type<>'talent' OR (_filters->>'talent'='agency_linked')=(cardinality(e.agency_ids)>0)) AND (_filters->>'source'='all' OR e.source=_filters->>'source') AND (_filters->>'status'='any' OR e.status=_filters->>'status') AND (jsonb_array_length(COALESCE(_filters->'agencies','[]'::jsonb))=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(_filters->'agencies') a WHERE a.value::uuid=ANY(e.agency_ids))))) AND (COALESCE(_filters->>'joined','')='' OR to_char(e.registered_at AT TIME ZONE 'Africa/Johannesburg','YYYY-MM')=_filters->>'joined') AND (COALESCE(_filters->>'search','')='' OR position(lower(_filters->>'search') in lower(e.name))>0) AND (_filters->>'stage'='all' OR e.stage=_filters->>'stage') AND (_filters->>'activity'='all' OR (_filters->>'activity'='active' AND e.sign_ins>0) OR (_filters->>'activity'='returning' AND e.active_days>=2) OR (_filters->>'activity'='dormant' AND e.dormant IS TRUE) OR (_filters->>'activity'='never' AND e.last_sign_in IS NULL AND e.capture_complete))) SELECT to_jsonb(f) FROM filtered f;
$fn$;
REVOKE ALL ON FUNCTION public.reports_people_rows(date,date,jsonb,timestamptz) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.reports_people_page(_from date,_to date,_filters jsonb,_limit integer DEFAULT 25,_offset integer DEFAULT 0,_sort text DEFAULT 'name',_direction text DEFAULT 'asc',_include_emails boolean DEFAULT false,_as_of timestamptz DEFAULT now(),_download boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$ DECLARE result jsonb; BEGIN
IF NOT public.reports_can('view_reports') OR (_download AND NOT public.reports_can('download_raw_data')) OR (_include_emails AND NOT public.reports_can('include_email_addresses')) THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Your Reports role does not allow this action.' USING ERRCODE='42501'; END IF;
IF _from IS NULL OR _to IS NULL OR _from>_to OR _as_of IS NULL OR _limit NOT BETWEEN 1 AND 200 OR _offset<0 OR _sort NOT IN ('name','sign_ins','active_days','registered_at','last_sign_in','documents','stage','status') OR _direction NOT IN ('asc','desc') OR _filters->>'accounts' NOT IN ('real','test','all') THEN RAISE EXCEPTION 'REPORT_FILTER_INVALID: Choose valid report filters.'; END IF;
WITH all_rows AS MATERIALIZED(SELECT r AS row FROM public.reports_people_rows(_from,_to,_filters,_as_of) r), page AS (SELECT row FROM all_rows ORDER BY CASE WHEN _direction='asc' AND _sort IN ('sign_ins','active_days','documents') THEN (row->>_sort)::numeric END ASC NULLS LAST,CASE WHEN _direction='desc' AND _sort IN ('sign_ins','active_days','documents') THEN (row->>_sort)::numeric END DESC NULLS LAST,CASE WHEN _direction='asc' AND _sort NOT IN ('sign_ins','active_days','documents') THEN lower(row->>_sort) END ASC NULLS LAST,CASE WHEN _direction='desc' AND _sort NOT IN ('sign_ins','active_days','documents') THEN lower(row->>_sort) END DESC NULLS LAST,row->>'person_id' LIMIT _limit OFFSET _offset)
SELECT jsonb_build_object('total',(SELECT count(*) FROM all_rows),'registered',(SELECT count(*) FROM all_rows WHERE (row->>'registered')::boolean),'rows',COALESCE((SELECT jsonb_agg(CASE WHEN _include_emails THEN row ELSE jsonb_set(jsonb_set(row,'{email}','null'),'{name}',to_jsonb(regexp_replace(row->>'name','[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}','[email omitted]','g'))) END) FROM page),'[]'::jsonb),'as_of',LEAST(_as_of,now())) INTO result; RETURN result; END $fn$;
REVOKE ALL ON FUNCTION public.reports_people_page(date,date,jsonb,integer,integer,text,text,boolean,timestamptz,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reports_people_page(date,date,jsonb,integer,integer,text,text,boolean,timestamptz,boolean) TO authenticated;
